<?php
declare(strict_types=1); require dirname(__DIR__,2).'/app/bootstrap.php'; $user=Auth::requireLogin(); Auth::requirePermission('trips.manage'); $pdo=Database::connection();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();try{$companyId=(int)($_POST['company_id']??0);if(($user['role']??'')==='company_manager')$companyId=(int)($user['company_id']??0);$origin=(int)($_POST['origin_city_id']??0);$dest=(int)($_POST['destination_city_id']??0);$depart=$_POST['departure_at']??'';$price=(float)($_POST['price']??0);$seats=(int)($_POST['seats_total']??0);if(!$companyId||!$origin||!$dest||$origin===$dest||!$depart||$price<0||$seats<1)throw new RuntimeException('أكمل البيانات المطلوبة بشكل صحيح.');$status=in_array($_POST['status']??'available',['available','paused','cancelled'],true)?$_POST['status']:'available';$pub=isset($_POST['is_published'])?1:0;$stmt=$pdo->prepare('INSERT INTO trips(company_id,origin_city_id,destination_city_id,departure_at,arrival_at,vehicle_type,price,currency,seats_total,status,is_published,details,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$companyId,$origin,$dest,$depart,$_POST['arrival_at']?:null,trim($_POST['vehicle_type']??''),$price,$_POST['currency']??'SAR',$seats,$status,$pub,trim($_POST['details']??''),$user['id']]);$tripId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO activity_logs(user_id,action_key,entity_type,entity_id,description,ip_address) VALUES(?,?,?,?,?,?)')->execute([$user['id'],'trip.created','trip',$tripId,'إضافة رحلة جديدة',$_SERVER['REMOTE_ADDR']??null]);redirect('/admin/trips.php?created=1');}catch(Throwable $e){$error=$e->getMessage();}}
$cities=$pdo->query('SELECT id,name_ar FROM cities WHERE is_active=1 ORDER BY name_ar')->fetchAll();$companies=$pdo->query("SELECT id,name FROM companies WHERE status='active' ORDER BY name")->fetchAll();$sql='SELECT t.*,c.name company_name,o.name_ar origin_name,d.name_ar destination_name FROM trips t JOIN companies c ON c.id=t.company_id JOIN cities o ON o.id=t.origin_city_id JOIN cities d ON d.id=t.destination_city_id';$args=[];if(($user['role']??'')==='company_manager'){$sql.=' WHERE t.company_id=?';$args[]=(int)($user['company_id']??0);}$sql.=' ORDER BY t.departure_at DESC LIMIT 200';$q=$pdo->prepare($sql);$q->execute($args);$rows=$q->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>إدارة الرحلات</title><link rel="stylesheet" href="/assets/css/app.css"><style>.wrap{padding:25px}.form-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.form-grid button{align-self:end}.panel{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}td,th{text-align:right;padding:10px;border-bottom:1px solid #eee;font-size:13px}@media(max-width:650px){.form-grid{grid-template-columns:1fr}}</style></head><body><header class="site-header"><a class="brand" href="/admin/index.php"><span class="brand-mark">م</span><b>إدارة الرحلات</b></a><a href="/admin/index.php">لوحة التحكم</a></header><main class="wrap"><h1>إضافة رحلة</h1><?php if($error):?><p class="notice"><?=e($error)?></p><?php endif;?><?php if(isset($_GET['created'])):?><p class="notice">تمت إضافة الرحلة.</p><?php endif;?><section class="panel"><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=e(Security::csrf())?>"><?php if(($user['role']??'')!=='company_manager'):?><label>شركة النقل<select name="company_id" required><option value="">اختر الشركة</option><?php foreach($companies as $c):?><option value="<?=(int)$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><?php endif;?><label>مدينة الانطلاق<select name="origin_city_id" required><?php foreach($cities as $c):?><option value="<?=(int)$c['id']?>"><?=e($c['name_ar'])?></option><?php endforeach;?></select></label><label>مدينة الوصول<select name="destination_city_id" required><?php foreach($cities as $c):?><option value="<?=(int)$c['id']?>"><?=e($c['name_ar'])?></option><?php endforeach;?></select></label><label>موعد الانطلاق<input type="datetime-local" name="departure_at" required></label><label>موعد الوصول<input type="datetime-local" name="arrival_at"></label><label>نوع المركبة<input name="vehicle_type" placeholder="حافلة سياحية"></label><label>سعر التذكرة<input type="number" name="price" min="0" step=".01" required></label><label>العملة<select name="currency"><option value="SAR">ريال سعودي</option><option value="YER">ريال يمني</option></select></label><label>عدد المقاعد<input type="number" name="seats_total" min="1" required></label><label>الحالة<select name="status"><option value="available">متاحة</option><option value="paused">متوقفة</option><option value="cancelled">ملغاة</option></select></label><label>نشر للعامة<input type="checkbox" name="is_published" checked></label><label style="grid-column:1/-1">تفاصيل إضافية<textarea name="details" rows="2"></textarea></label><button class="btn btn-primary" type="submit">حفظ الرحلة</button></form></section><h2>الرحلات المسجلة</h2><section class="panel"><table><thead><tr><th>الشركة</th><th>المسار</th><th>الموعد</th><th>السعر</th><th>المقاعد</th><th>الحالة</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['company_name'])?></td><td><?=e($r['origin_name'].' ← '.$r['destination_name'])?></td><td><?=e($r['departure_at'])?></td><td><?=e($r['price'].' '.$r['currency'])?></td><td><?=(int)$r['seats_total']?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">لا توجد رحلات.</td></tr><?php endif;?></tbody></table></section></main></body></html>